local function BuildFrame() if frame then return end; frame=CreateFrame("Frame","CCRaidToolsRaidCheckFrame",UIParent,"BackdropTemplate"); frame:SetSize(625,520); frame:SetPoint("CENTER",320,0); frame:SetMovable(true); frame:EnableMouse(true); frame:RegisterForDrag("LeftButton"); frame:SetScript("OnDragStart",frame.StartMoving); frame:SetScript("OnDragStop",frame.StopMovingOrSizing); C.ApplyPanelSkin(frame); frame:SetScript("OnHide",function() StopTicker(); StopCountdown(); wipe(auraStatuses) end); local title=frame:CreateFontString(nil,"OVERLAY","GameFontNormal"); title:SetPoint("TOP",0,-7); title:SetText("CC RaidTools - Ready Check"); title:SetTextColor(C.BRAND_R,C.BRAND_G,C.BRAND_B); local close=CreateFrame("Button",nil,frame); close:SetSize(28,28); close:SetPoint("TOPRIGHT",-2,-2); close:EnableMouse(true); local closeText=close:CreateFontString(nil,"OVERLAY"); closeText:SetPoint("CENTER",0,1); closeText:SetFont("Fonts\\FRIZQT__.TTF",24,"OUTLINE"); closeText:SetText("×"); closeText:SetTextColor(1,1,1,1); closeText:SetShadowColor(0,0,0,.8); closeText:SetShadowOffset(1,-1); close:SetScript("OnClick",function() frame:Hide() end); frame.closeButton=close; local h=CreateFrame("Frame",nil,frame); h:SetPoint("TOPLEFT",12,-30); h:SetSize(590,20); local function H(txt,x,w,j)local f=h:CreateFontString(nil,"OVERLAY","GameFontNormalSmall"); f:SetPoint("LEFT",x,0); f:SetWidth(w); f:SetJustifyH(j or "CENTER"); f:SetText(txt); f:SetTextColor(C.BRAND_R,C.BRAND_G,C.BRAND_B); return f end; frame.header={name=H("0/0",4,125,"LEFT"),ready=H("Prêt",130,48),food=H("Repas",179,48),flask=H("Flacon",228,48),rune=H("Rune",277,48),vantus=H("Vantus",326,52),intel=H("Intel",380,38),ap=H("PA",419,38),druid=H("Druid",458,38),stam=H("Endu",497,38),sham=H("Sham",536,38),bronze=H("Bronze",575,48)}; frame._ccrtCountText=frame.header.name; local s=CreateFrame("ScrollFrame",nil,frame,"UIPanelScrollFrameTemplate"); s:SetPoint("TOPLEFT",12,-52); s:SetSize(580,445); C.SkinScrollBar(s); local child=Create